// ── CONFIG ──────────────────────────────────────────────────
const cfg = $('Set Config').first().json;
const token = $('Get Shopify Token').first().json.data.token;
const shopDomain = cfg.SHOP_DOMAIN;
const apiVersion = '2024-01';

// ── IST DATE HELPERS ─────────────────────────────────────────
const IST_MS = 19800000; // 5h30m
function istMidnightUTC(offsetDays) {
  const now = new Date(Date.now() + IST_MS);
  const ist = new Date(now.getFullYear(), now.getMonth(), now.getDate() + offsetDays);
  return new Date(Date.UTC(ist.getFullYear(), ist.getMonth(), ist.getDate()) - IST_MS);
}
const minUTC = istMidnightUTC(-1).toISOString();
const maxUTC = istMidnightUTC(0).toISOString();
const nowIST = new Date(Date.now() + IST_MS);
const yd = new Date(nowIST.getFullYear(), nowIST.getMonth(), nowIST.getDate() - 1);
const dateStr = `${yd.getFullYear()}-${String(yd.getMonth()+1).padStart(2,'0')}-${String(yd.getDate()).padStart(2,'0')}`;

// ── CATEGORIZER (mirrors categorizer.py exactly) ─────────────
const NAMED = {save30:'SAVE30',save25:'SAVE25',save35:'SAVE35',stealdeal:'STEALDEAL',buy3:'BUY3','buy3at699':'BUY3@699',buy4:'BUY4',buy5:'BUY5',buy6:'BUY6',buy10:'BUY10',b3p2:'B3P2',b2g2:'B2G2',modern20:'MODERN20',gpay:'GPAY',fullcb:'FULLCB',freelipstick:'FREELIPSTICK',lips5:'LIPS5',free5:'FREE5',free6:'FREE6',freevanity:'FREEVANITY',luxevanity:'LUXEVANITY',freekit:'FREEKIT',lipluxe:'LIPLUXE','5pcs':'5PCS','3pcs':'3PCS','4pcs':'4PCS',special4:'SPECIAL4',special5:'SPECIAL5',special6:'SPECIAL6',get4:'GET4',get2:'GET2',luxe3:'LUXE3','6pcskit':'6PCS KIT','4pcskit':'4PCS KIT'};
const NAMED_ORDER = ['save30','save25','save35','stealdeal','buy3','buy3at699','buy4','buy5','buy6','buy10','b3p2','b2g2','modern20','gpay','fullcb','freelipstick','lips5','free5','free6','freevanity','luxevanity','freekit','lipluxe','5pcs','3pcs','4pcs','special4','special5','special6','get4','get2','luxe3','6pcskit','4pcskit'];
const ALL_COLS = [...NAMED_ORDER, 'pp', 'influencer', 'others'];
const EXCL_S = ['c2p','prepaid','bundle','cashback'];
const EXCL_E = new Set(['nil','creatororder','customdiscount']);
const PP_S = ['unloq','wishlink','ck'];
const OTH_P = ['emp','swiss','welcome','beauty','sbn','sb','bogo'];

function norm(c) { return c.toLowerCase().replace(/[\s-]/g,'').trim(); }
function cat(raw) {
  const k = norm(raw), u = raw.replace(/\s/g,'').toUpperCase();
  if (EXCL_E.has(k)) return 'excluded';
  for (const s of EXCL_S) if (k.includes(s)) return 'excluded';
  if (NAMED[k]) return k;
  for (const s of PP_S) if (k.includes(s)) return 'pp';
  for (const p of OTH_P) if (k.startsWith(p)) return 'others';
  if (/^[A-Za-z]{3,}\d{2,}$/.test(raw.trim())) return 'influencer';
  if (/^[A-Z0-9]{8,}$/.test(u)) return 'pp';
  return 'others';
}

// ── FETCH ALL ORDERS (cursor pagination) ─────────────────────
let orders = [];
let nextUrl = `https://${shopDomain}/admin/api/${apiVersion}/orders.json?status=any&fields=id,created_at,discount_codes,total_discounts&limit=250&created_at_min=${minUTC}&created_at_max=${maxUTC}`;
while (nextUrl) {
  const res = await this.helpers.httpRequest({
    method: 'GET',
    url: nextUrl,
    headers: { 'X-Shopify-Access-Token': token },
    returnFullResponse: true
  });
  orders = orders.concat(res.body?.orders || []);
  const lh = res.headers?.link || '';
  const m = lh.match(/<([^>]+)>;\s*rel="next"/);
  nextUrl = m ? m[1] : null;
}

// ── AGGREGATE ────────────────────────────────────────────────
let totalOrders = 0;
const B = {};
for (const k of ALL_COLS) B[k] = { count: 0, disc: 0 };

for (const o of orders) {
  totalOrders++;
  const codes = o.discount_codes || [];
  for (const dc of codes) {
    const c = cat(dc.code || '');
    if (c === 'excluded') continue;
    const t = B[c] !== undefined ? c : 'others';
    B[t].count++;
    B[t].disc += parseFloat(dc.amount || '0');
  }
}

const totalCoupon = ALL_COLS.reduce((s, k) => s + B[k].count, 0);
const totalDiscRaw = ALL_COLS.reduce((s, k) => s + B[k].disc, 0);
const overallPct = totalOrders > 0 ? (totalCoupon / totalOrders * 100).toFixed(1) : '0.0';

// ── PERCENTAGE ROUNDING (largest-remainder, mirrors Python) ──
function lrPct(buckets, keys, total) {
  if (!total) return Object.fromEntries(keys.map(k => [k, '0.0']));
  const exact = Object.fromEntries(keys.map(k => [k, buckets[k].count / total * 1000]));
  const floored = Object.fromEntries(keys.map(k => [k, Math.floor(exact[k])]));
  const remainder = Object.fromEntries(keys.map(k => [k, exact[k] - floored[k]]));
  let extra = 1000 - keys.reduce((s, k) => s + floored[k], 0);
  keys.slice().sort((a, b) => remainder[b] - remainder[a]).slice(0, extra).forEach(k => floored[k]++);
  return Object.fromEntries(keys.map(k => [k, (floored[k] / 10).toFixed(1)]));
}
const pcts = lrPct(B, ALL_COLS, totalCoupon);

// ── BUILD BREAKDOWN (non-zero rows, sorted count desc) ───────
const DISPLAY = { pp: 'PP (Paid Promotion)', influencer: 'Influencer / Marketing', others: 'Others' };
const breakdown = ALL_COLS
  .map(k => ({
    display: NAMED[k] || DISPLAY[k] || k.toUpperCase(),
    count: B[k].count,
    pct: pcts[k],
    disc: Math.round(B[k].disc * 0.25)
  }))
  .filter(r => r.count > 0)
  .sort((a, b) => b.count - a.count);

return [{ json: {
  dateStr, totalOrders, totalCoupon, overallPct,
  totalDisc: Math.round(totalDiscRaw * 0.25),
  breakdown
} }];
